/** Card face image for a CardDef.art web path like '/cards/0001.png'. */
export function cardImage(art: string): ImageSourcePropType | undefined {
  const key = art.replace(/^.*\//, '').replace(/\.[^.]+$/, '');
  return CARD_IMAGES[key];
}

export function cardBack(faction: string): ImageSourcePropType | undefined {
  return CARD_BACKS[faction + '_back'] ?? CARD_BACKS['unknown_back'];
}

