/** Art for a location at board slot index (0=left, 1=center, 2=right). */
export function locationImage(locId: string, slotIndex: number): ImageSourcePropType | undefined {
  const prefix = LOCATION_ART[locId] ?? locId;
  return LOCATION_IMAGES[`${prefix}_${slotIndex + 1}`];
}
